    "causal_mechanism": {
      "status": "scored",
      "score": 1,
      "event_ids": ["A9", "A10"],
      "reason": "The best theory, T1 (A9), names a benefit: smart-home integration and reliability lead to purchase. The 'why behaviour changes' step is asserted ('growing awareness... makes Testo instruments attractive') rather than explained. Value capture is a list of options (premium, subscription, partnerships) with no chain showing why Testo, rather than a competitor, captures value."
    },
    "distinct_theories": {
      "status": "scored",
      "score": 1,
      "event_ids": ["A9", "A10"],
      "reason": "T1 and T2 share the same customers (homeowners and small businesses), the same use case (home energy efficiency) and largely the same channels. They differ only in which purchase motive is emphasised (smart features versus bill savings). These are close rewordings of one idea, not rivals implying different products, customers or channels."
    },
    "assumptions_predictions": {
      "status": "scored",
      "score": 2,
      "event_ids": ["A9", "A15"],
      "reason": "T1's assumptions and predictions (A9) are observable, with purchase-intent and sales thresholds. The thresholds are arbitrary assumptions, not observed figures. They also do not threaten the theory consistently: A9 asks for 20% higher intent, while the A15 decision rule proceeds at 5 percentage points. Missing the stated prediction therefore would not put T1 in trouble."
    },
    "evidence_judgement": {
      "status": "scored",
      "score": 1,
      "event_ids": ["A11", "A12", "A14", "A17"],
      "reason": "A11, A12 and A14 label sources as 'independent_study' when the dossier classes them as verified_observation. A11 and A12 use Airthings' segment data with no note that Airthings is a different company and cannot show anything about Testo's consumer reach. A17 then cites 'the Consumer segment decline' as if it were Testo's evidence. The 'does not show' notes are generic and do not address company, date, place or fit with the customer group. No source distinctions are made beyond this."
    },
    "seeking_challenge": {
      "status": "scored",
      "score": 1,
      "event_ids": ["A13"],
      "reason": "A13 runs one search against T1 and finds testo-smartprobes-technicians, testo-suffolk-borrow and testo-uswitch-damp, but none of these is assessed. Two are potentially challenging: Testo's smart products are positioned for technicians, and Suffolk residents borrow thermal cameras free rather than buy them. Neither is reported or weighed. This is a gesture rather than a genuine search with a fair report."
    },
    "experiment_design": {
      "status": "scored",
      "score": 1,
      "event_ids": ["A15"],
      "reason": "A15 is costed (€18,000, 10 weeks) and within budget. However, the decision rule lets both arms pass at 5 percentage points and gives no rule for choosing between them. The thresholds conflict with the stated predictions (20% and 15%). Stated intent in a simulated choice task cannot establish real purchase behaviour. The test cannot cleanly separate T1 from T2, and it never tests the 'no expansion' or small-trades alternatives from A1."
    },
    "revision": {
      "status": "not_applicable",
      "score": null,
      "event_ids": [],
      "reason": "Revision is excluded from packet.applicable_dimensions, and no update was scheduled or delivered."
    },
    "recommendation": {
      "status": "scored",
      "score": 1,
      "event_ids": ["A16", "A17"],
      "reason": "A17 commits to a next action and states reversal conditions, but the position is unsupported. T1 is rated 'likely' although every assessment (A11, A12, A14) was neutral. The recommendation says 'Invest' and launch before the test has run, and it relies on misattributed Airthings evidence. The recommendation and uncertainty text are also truncated."
    }
  },
  "red_flags": [
    {
      "kind": "unsupported_inference",
      "event_ids": ["A11", "A12", "A14", "A16", "A17"],
      "reason": "Every assessment was neutral, yet A16 and A17 rate T1 'likely' and recommend investing. No evidence supports the shift from neutral to likely."
    },
    {
      "kind": "misleading_quote",
      "event_ids": ["A11", "A17"],
      "reason": "The Airthings revenue-decline excerpt is used as evidence about Testo's consumer position. A17 refers to 'the Consumer segment decline' as Testo's, misreading which company the source describes."
    },
    {
      "kind": "unsupported_inference",
      "event_ids": ["A11", "A12", "A14"],
      "reason": "Sources are relabelled 'independent_study' when the dossier classes them as verified_observation. This misstates the type of evidence."
    },
    {
      "kind": "non_discriminating_test",
      "event_ids": ["A15"],
      "reason": "Both arms can meet the 5 percentage point rule at once, with no rule for choosing between them. The thresholds also contradict the stated predictions, so the test does not separate T1 from T2."
    },
    {
      "kind": "other",
      "event_ids": ["A13"],
      "reason": "The challenge search surfaced possibly contrary sources (technician positioning, free library loans of thermal cameras) that were never assessed or reported."
    }
  ],
  "suitable_for_training": false,
  "screen_reason": "The episode is complete, but it contains a material unsupported update (T1 rated likely from neutral evidence), misattributes Airthings data to Testo, and proposes a test that cannot separate the two theories. Each is a critical error."
}

